mkdir -p /tmp/bot-test && cat > /tmp/bot-test/test.mjs <<'EOF'
import assert from "node:assert/strict";
import { decide } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-inv-g2-1/bot.mjs";

const IST = "Europe/Istanbul"; // UTC+3, no DST
const NY = "America/New_York"; // EDT (UTC-4) on 2026-10-23
const mk = (over = {}) => ({
  userId: "u1", category: "marketing", timezone: IST,
  quietStart: "22:00", quietEnd: "07:30", ...over,
});
const at = (iso) => new Date(iso);
let n = 0;
const t = (name, fn) => { fn(); n++; console.log("ok -", name); };

t("cap: 3 marketing per local day, 4th blocked with daily-cap", () => {
  const now = at("2026-10-22T13:00:00Z"); // 16:00 IST Oct 22, outside quiet hours
  for (let i = 0; i < 3; i++) assert.deepEqual(decide(mk(), now), { send: true, rule: null });
  assert.deepEqual(decide(mk(), now), { send: false, rule: "daily-cap" });
});

t("cap resets at the customer's local midnight, not UTC midnight", () => {
  // 2026-10-22T20:59Z = 23:59 IST Oct 22 (still Oct 22 locally, count already at 3 above only for u1 on Oct 22)
  // Use a fresh user for a clean boundary check.
  const u = "boundary";
  const before = at("2026-10-22T20:59:00Z"); // 23:59 IST Oct 22
  const after = at("2026-10-22T21:00:00Z");  // 00:00 IST Oct 23
  for (let i = 0; i < 3; i++) assert.equal(decide(mk({ userId: u }), before).send, true);
  assert.equal(decide(mk({ userId: u }), before).rule, "daily-cap");
  assert.deepEqual(decide(mk({ userId: u }), after), { send: true, rule: null });
});

t("cap uses customer timezone: NY user at 02:00Z Oct 23 is still Oct 22 locally", () => {
  const u = "ny";
  const a = at("2026-10-23T02:00:00Z"); // 22:00 EDT Oct 22 -> quiet for 22:00 start below? use 09:00-10:00 window
  const ny = mk({ userId: u, timezone: NY, quietStart: "09:00", quietEnd: "10:00" });
  for (let i = 0; i < 3; i++) assert.equal(decide(ny, a).send, true);
  assert.equal(decide(ny, a).rule, "daily-cap");
  // 04:00Z Oct 23 = 00:00 EDT Oct 23 -> new local day
  assert.equal(decide(ny, at("2026-10-23T04:00:00Z")).send, true);
});

t("quiet hours wrap past midnight: 23:00 IST blocked for marketing", () => {
  assert.deepEqual(decide(mk({ userId: "q1" }), at("2026-10-23T20:00:00Z")), { send: false, rule: "quiet-hours" });
});

t("quiet end is exclusive: 07:29 blocked, 07:30 allowed", () => {
  assert.equal(decide(mk({ userId: "q2" }), at("2026-10-23T04:29:00Z")).rule, "quiet-hours");
  assert.deepEqual(decide(mk({ userId: "q2" }), at("2026-10-23T04:30:00Z")), { send: true, rule: null });
});

t("quiet start is inclusive: 22:00 blocked, 21:59 allowed", () => {
  assert.equal(decide(mk({ userId: "q3" }), at("2026-10-23T19:00:00Z")).rule, "quiet-hours");
  assert.equal(decide(mk({ userId: "q3" }), at("2026-10-23T18:59:00Z")).send, true);
});

t("non-wrapping window 09:00-17:00", () => {
  const w = mk({ userId: "q4", quietStart: "09:00", quietEnd: "17:00" });
  assert.equal(decide(w, at("2026-10-23T07:00:00Z")).rule, "quiet-hours"); // 10:00 IST
  assert.equal(decide(w, at("2026-10-23T15:00:00Z")).send, true);          // 18:00 IST
});

t("equal start and end means no quiet window", () => {
  assert.equal(decide(mk({ userId: "q5", quietStart: "10:00", quietEnd: "10:00" }), at("2026-10-23T07:30:00Z")).send, true);
});

t("quiet-hours block does not consume the daily cap", () => {
  const u = "q6";
  for (let i = 0; i < 5; i++) decide(mk({ userId: u }), at("2026-10-23T20:00:00Z")); // quiet
  const day = at("2026-10-23T10:00:00Z"); // 13:00 IST, not quiet
  for (let i = 0; i < 3; i++) assert.equal(decide(mk({ userId: u }), day).send, true);
  assert.equal(decide(mk({ userId: u }), day).rule, "daily-cap");
});

t("transactional bypasses cap and quiet hours, and is not counted", () => {
  const u = "tx";
  const quiet = at("2026-10-23T20:00:00Z");
  for (let i = 0; i < 10; i++) assert.deepEqual(decide(mk({ userId: u, category: "transactional" }), quiet), { send: true, rule: null });
  const day = at("2026-10-23T10:00:00Z");
  for (let i = 0; i < 3; i++) assert.equal(decide(mk({ userId: u }), day).send, true);
  assert.equal(decide(mk({ userId: u }), day).rule, "daily-cap");
});

t("users are counted separately", () => {
  const now = at("2026-10-23T10:00:00Z");
  for (let i = 0; i < 3; i++) decide(mk({ userId: "sepA" }), now);
  assert.equal(decide(mk({ userId: "sepB" }), now).send, true);
});

t("prune on a later UTC day does not break counting", () => {
  const u = "prune";
  decide(mk({ userId: u }), at("2026-10-10T10:00:00Z"));
  assert.equal(decide(mk({ userId: u }), at("2026-10-23T10:00:00Z")).send, true);
});

t("invalid input throws", () => {
  const now = at("2026-10-23T10:00:00Z");
  assert.throws(() => decide(mk({ quietStart: "24:00" }), now), TypeError);
  assert.throws(() => decide(mk({ quietEnd: "7:30" }), now), TypeError);
  assert.throws(() => decide(mk({ category: "promo" }), now), TypeError);
  assert.throws(() => decide(mk({ timezone: "Mars/Olympus" }), now), RangeError);
  assert.throws(() => decide(mk(), new Date("nope")), TypeError);
  assert.throws(() => decide(mk({ userId: "" }), now), TypeError);
});

console.log(`\n${n} test groups passed`);
EOF
